import type { Gender } from '@/types';

/**
 * 体重 & 维度页的背景剪影（男女两套，480x1200）。
 * 内联 base64：静态图片路径在 H5 预览沙箱里会 404，内联最稳。
 * 想换图时把下面两段 base64 换掉即可（暗色底 + 橙色描边的人形最合适）。
 */
const MALE_ART = 'data:image/jpeg;base64,';
const FEMALE_ART = 'data:image/jpeg;base64,';

export const BODY_ART: Record<Gender, string> = {
  male: MALE_ART,
  female: FEMALE_ART
};
